<?php

declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Controller;use App\Core\Database;use App\Core\Request;use App\Services\ProgressService;
final class LessonController extends Controller{
public function show(Request $request,int $id):void{$pdo=Database::connection();$s=$pdo->prepare("SELECT l.*,p.title phase_title,p.id phase_id,p.is_required phase_required,p.module_id,m.title module_title FROM lessons l JOIN phases p ON p.id=l.phase_id JOIN modules m ON m.id=p.module_id WHERE l.id=:id AND l.status='published' LIMIT 1");$s->execute(['id'=>$id]);$lesson=$s->fetch();if(!$lesson){http_response_code(404);$this->view('errors/404');return;}$b=$pdo->prepare("SELECT * FROM lesson_blocks WHERE lesson_id=:l ORDER BY position");$b->execute(['l'=>$id]);$blocks=$b->fetchAll();$i=max(1,(int)$request->input('bloco',1));$i=min($i,max(1,count($blocks)));$current=$blocks[$i-1]??null;if($current&&Auth::id())(new ProgressService())->registerBlockView((int)Auth::id(),$id,(int)$current['id'],$i);$p=$pdo->prepare("SELECT * FROM user_lesson_progress WHERE user_id=:u AND lesson_id=:l LIMIT 1");$p->execute(['u'=>Auth::id(),'l'=>$id]);$this->view('student/lesson',['title'=>$lesson['title'],'lesson'=>$lesson,'blocks'=>$blocks,'currentBlock'=>$current,'currentIndex'=>$i,'totalBlocks'=>count($blocks),'progress'=>$p->fetch()?:null,'user'=>Auth::user()],'layouts/student');}}
